SELECT 'gongkao', '论证与素材运用', 'kp-sl-essay-argument', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "大作文：论证与素材运用"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "理证为主，例证为辅。素材必须紧贴分论点。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、分论点段落的“三明治”结构"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "顶层：抛出分论点（亮明观点）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "夹心：用材料里的例子（或自带的金句/名人名言）去证明这个分论点。注意：抄材料例子时必须高度概括，绝不能大段照抄原文！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "底层：分析这个例子为什么能证明你的观点，并提出解决这个层面的微观对策或总结。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "例子和论点脱节：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "分论点是“要加强基层治理”，举的例子却是“科学家发射了火箭”。驴唇不对马嘴。例子必须和分论点高度贴合。"}]}]}]}$$ AS jsonb), NULL, '论证与素材运用的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "大作文", "论证素材"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_essay_argument", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
